	'upd_req_writable_help' => "PHP 以“%1\$s”身份运行，只能读取这些文件夹：它们属于上传它们的用户（例如通过 SFTP），权限为常见的 755（其他人：只读）。\n通过 SSH 修复（文件夹：%2\$s）：\n• sudo chown -R %1\$s %2\$s – 文件归 PHP 所有（之后通过 SFTP 只能读取）\n• 或共享：sudo chown -R 你的用户:%1\$s %2\$s，并对文件夹执行 chmod 2775、对文件执行 664\n没有 SSH 时，在 SFTP 客户端中（例如 FileZilla：右键 → 文件权限）：将文件夹设为 777（所有人可读、写、执行——文件夹的“执行”表示“可进入”），递归子目录，仅应用于目录。安装更新后再改回 755。\n或手动更新：将 nunext.zip 中的文件上传覆盖旧文件。",
